/bin/zsh -lc "node --input-type=module - <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
const kb = JSON.parse(readFileSync('server/kristy_perimeter_kb.json', 'utf8'));
const baseline = JSON.parse(execFileSync('git', ['show', 'HEAD:server/kristy_perimeter_kb.json'], { maxBuffer: 64 << 20 }).toString());
const ids = ['egg_duck_quail', 'label_cage_free', 'label_pasture_raised_feed'];
const pins = readFileSync('server/test/acceptance/twoLinePin.js', 'utf8');
const changes = [];
for (const before of baseline.entries) {
  const now = kb.entries.find(e => e.id === before.id);
  assert.ok(now);
  if (JSON.stringify(now) === JSON.stringify(before)) continue;
  assert.ok(ids.includes(now.id), "'`unintended card change ${now.id}`);
  const pin = JSON.parse(pins.match(new RegExp(`  "${now.id}": ('"\\\\{[\\\\s\\\\S]*?\\\\n  \\\\}),"'`))[1]);
  const fields = Object.keys(now).filter(key => JSON.stringify(now[key]) !== JSON.stringify(before[key]));
  for (const field of fields) assert.deepEqual(pin[field], now[field], `${now.id}.${field} missing from pin`);
  for (const source of before.sources) assert.ok(now.sources.some(s => JSON.stringify(s) === JSON.stringify(source)), `${now.id} lost a source`);
  assert.ok(now.sources.slice(before.sources.length).every(s => typeof s === '"'object' && s.name && s.url));
  for (const field of ['aliases', 'asked_as', 'labels_decoded']) assert.deepEqual(now[field], before[field], "'`${now.id}.${field}`);
  const text = JSON.stringify(Object.fromEntries(Object.entries(now).filter(([key]) => !['"'sources','aliases','asked_as'].includes(key))));
  assert.doesNotMatch(text, /\\b(?:causes?|prevents?|lowers? (?:the )?risk|carcinogen\\w*|cancer|healthier for you|I|me|my)\\b/);
  changes.push({id: now.id, fields});
}
assert.equal(kb.entries.length, baseline.entries.length);
assert.deepEqual(changes.map(e => e.id).sort(), ids.toSorted());
console.log(JSON.stringify({audit: 'Only the three scoped cards changed; every changed field is pinned; existing sources and label terms retained.', changes}, null, 2));
NODE"

